export function canCompleteCourses(count,prerequisites) {
  const adj=Array.from({length:count},()=>[]),indegree=Array(count).fill(0);
  for(const [course,required] of prerequisites){adj[required].push(course);indegree[course]++;}
  const q=[];for(let i=0;i<count;i++)if(!indegree[i])q.push(i);
  let taken=0;for(let h=0;h<q.length;h++){const u=q[h];taken++;for(const v of adj[u])if(--indegree[v]===0)q.push(v);}
  return taken===count;
}
